import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 55 Not a gold mine","description":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 55 Not a gold mine","description":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 54 Sticky fingers","link":"/life/english/new-concept/book-2/unit-03/lesson-054"},"next":{"text":"第二册：实践与进步 · Lesson 56 Faster than sound!","link":"/life/english/new-concept/book-2/unit-03/lesson-056"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 54 Sticky fingers","link":"/life/english/new-concept/book-2/unit-03/lesson-054"},"next":{"text":"第二册：实践与进步 · Lesson 56 Faster than sound!","link":"/life/english/new-concept/book-2/unit-03/lesson-056"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-055.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-055.md"}'),i={name:"life/english/new-concept/book-2/unit-03/lesson-055.md"};function l(s,e,d,r,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-55-not-a-gold-mine" tabindex="-1">第二册：实践与进步 · Lesson 55 Not a gold mine <a class="header-anchor" href="#第二册-实践与进步-·-lesson-55-not-a-gold-mine" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 55 Not a gold mine&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>挖掘者期待财宝，却只发现有研究价值的普通物件；练习 used to 和完成后的反思。本课的语言观察是：used to believe 表过去常持有的看法，现在已改变；once believed 则只说明曾相信，不一定强调长期习惯。完成学习后，请写一个预期落空但产生另一种价值的故事，区分原先信念与发现。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>gold</td><td>/ɡəʊld/</td><td>n.</td><td>金</td><td>a piece of gold</td></tr><tr><td>mine</td><td>/maɪn/</td><td>n.</td><td>矿井</td><td>a coal mine</td></tr><tr><td>dig</td><td>/dɪɡ/</td><td>v.</td><td>挖</td><td>dig a hole</td></tr><tr><td>treasure</td><td>/ˈtreʒə/</td><td>n.</td><td>财宝</td><td>buried treasure</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>dig for — 挖掘寻找某物</li><li>turn out to be — 结果证明是，与原先预期可能不同</li></ul><h2 id="语法讲解-一般过去时与事件顺序" tabindex="-1">语法讲解：一般过去时与事件顺序 <a class="header-anchor" href="#语法讲解-一般过去时与事件顺序" aria-label="Permalink to &quot;语法讲解：一般过去时与事件顺序&quot;">​</a></h2><p>一般过去时把动作放在已经结束的过去时间内，肯定句用动词过去式；疑问和否定借助 did 后，实义动词恢复原形。be 的过去式是 was/were，不再加 did。叙事中连续的过去式通常按出现顺序推进情节；单凭一句过去式不能推断动作持续多久。先确定时间范围，再选择动词形式，不要把汉语中的“了”机械地翻译成完成时。本课应用：used to believe 表过去常持有的看法，现在已改变；once believed 则只说明曾相信，不一定强调长期习惯。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>People once believed that the field contained gold.</p></blockquote><p>人们曾相信那片田地含有黄金。</p><p>believed 是主句过去式，that 从句 contained 是当时的信念内容，不代表作者认可它为事实。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>gold 是不可数物质名词，通常不写 a gold；a piece of gold 才表示一块。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 gold 与 old 的起始辅音，朗读 found only 时让 only 修饰实际发现。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>People once believed that the field contained gold. A survey found only old pottery. The village opened a small historical display instead.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个预期落空但产生另一种价值的故事，区分原先信念与发现。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：believed 是主句过去式，that 从句 contained 是当时的信念内容，不代表作者认可它为事实。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：gold 是不可数物质名词，通常不写 a gold；a piece of gold 才表示一块。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 dig 的过去式：They ___ three holes.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> dug</p><p><strong>解析：</strong> dig 的过去式和过去分词均为 dug。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>调查发现了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Old pottery.</p><p><strong>解析：</strong> 不是黄金；instead 表后续用途发生改变。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“一块黄金”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> a piece of gold</p><p><strong>解析：</strong> gold 不可数，借助 piece 计数。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般过去时与事件顺序。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-054">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-056">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
